style:
/* 素钉 —— 「个人简历」大标头，浅灰图钉标题带 */

.tw-suding.layout-band.resume-paper .paper-flow::before {
  content: "个人简历";
  display: block;
  margin-bottom: 6mm;
  padding-bottom: 3.4mm;
  border-bottom: 0.4mm solid #d7dde2;
  color: #1e272e;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 2.6);
  font-weight: 700;
  letter-spacing: 0.14em;
}

.tw-suding.layout-band.resume-paper .paper-header {
  position: relative;
  margin: 0 -15mm 7mm;
  padding: 5mm 15mm 5mm 15mm;
  background: #f2f4f6;
  border: none;
  align-items: flex-start;
  gap: 7mm;
  print-color-adjust: exact;
}

.tw-suding.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-suding.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 33mm;
  border: 0.4mm solid #dbe1e6;
  border-radius: 0;
  box-shadow: none;
}

.tw-suding.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-suding.layout-band.resume-paper .paper-name {
  color: #1c242b;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.3);
  letter-spacing: 0.06em;
}

.tw-suding.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6b757e;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-suding.layout-band.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: #3c464f;
  font-size: calc(var(--paper-base-size) * 0.94);
  font-weight: 400;
}

.tw-suding.layout-band.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 6mm;
  margin-top: 3mm;
  color: #3b454d;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-suding.layout-band.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-suding.layout-band.resume-paper .paper-contact + .paper-contact::before {
  content: "|";
  left: -3.4mm;
  color: #c3cbd1;
}

.tw-suding.layout-band.resume-paper .paper-contact__label {
  color: #79848d;
}

/* 标题：浅灰整条 + 左侧小图钉 */
.tw-suding.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.6mm;
  margin-bottom: 3.4mm;
  padding: 1.4mm 3.2mm;
  background: #e9edf0;
  border-radius: 0;
  color: #2a343c;
  font-size: calc(var(--paper-base-size) * 1.02);
  font-weight: 600;
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-suding.layout-band.resume-paper .paper-style-block .paper-section__title::before {
  content: "";
  flex: 0 0 auto;
  width: 1.8mm;
  height: 1.8mm;
  border-radius: 50%;
  background: #8d97a0;
  print-color-adjust: exact;
}

.tw-suding.layout-band.resume-paper .paper-section__body {
  color: #333d45;
}

.tw-suding.layout-band.resume-paper .paper-item-title {
  color: #1c242b;
}

.tw-suding.layout-band.resume-paper .paper-item-period {
  color: #76818a;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-suding.layout-band.resume-paper .paper-item-sub {
  color: #46515a;
}

.tw-suding.layout-band.resume-paper .paper-rich ul,
.tw-suding.layout-band.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-suding.layout-band.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.6mm;
}

.tw-suding.layout-band.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1.1mm;
  height: 1.1mm;
  border-radius: 50%;
  background: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-suding.layout-band.resume-paper .paper-note__tag {
  color: #2a343c;
  font-weight: 600;
}

.tw-suding.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e3e8eb;
  color: #9ea8b0;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-suding.resume-paper .paper-rich ul[data-list],
.tw-suding.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-suding.resume-paper .paper-rich ul[data-list] > li,
.tw-suding.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-suding.resume-paper .paper-rich ul[data-list] > li::before,
.tw-suding.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-suding.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-suding.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-suding.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-suding.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-suding.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-suding.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-suding.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-suding.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-suding.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-suding.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-suding.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-suding.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-suding.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-suding.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-suding.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-suding.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-suding.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-suding.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-suding.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-suding.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-suding.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-suding.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-suding.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-suding.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
